{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { resolve } from 'node:path';

const port = Number(process.env.PORT || 8080);
const dbPath = resolve(process.env.DB_PATH || './workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
const projectColumns = db.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
}
if (!projectColumns.some(column => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal'");
}
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
const taskColumns = db.prepare('PRAGMA table_info(tasks)').all();
if (!taskColumns.some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'");
}
if (!taskColumns.some(column => column.name === 'due_date')) {
  db.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT');
}
if (!taskColumns.some(column => column.name === 'sort_order')) {
  db.exec('ALTER TABLE tasks ADD COLUMN sort_order INTEGER NOT NULL DEFAULT 0');
  db.exec('UPDATE tasks SET sort_order = id');
}

function isValidDueDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

const indexHtml = await readFile(new URL('./index.html', import.meta.url));
const appJs = await readFile(new URL('./app.js', import.meta.url));
const stylesCss = await readFile(new URL('./styles.css', import.meta.url));
const json = (res, status, data) => {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
};
async function readBody(req) {
  let body = '';
  for await (const chunk of req) body += chunk;
  try { return JSON.parse(body); } catch { return null; }
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  if (req.method === 'GET' && url.pathname === '/health') return json(res, 200, { status: 'ok' });
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    return json(res, 200, db.prepare(`SELECT p.id, p.name, p.archived, p.default_priority AS defaultPriority,
      COUNT(t.id) AS totalCount, SUM(CASE WHEN t.completed = 1 THEN 1 ELSE 0 END) AS completedCount
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      GROUP BY p.id ORDER BY p.id`).all().map(project => ({
        ...project, archived: Boolean(project.archived),
        totalCount: Number(project.totalCount), completedCount: Number(project.completedCount),
      })));
  }
  const projectRoute = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectRoute && req.method === 'PATCH') {
    const data = await readBody(req);
    if (['Low', 'Normal', 'High'].includes(data?.defaultPriority)) {
      const result = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?').run(data.defaultPriority, Number(projectRoute[1]));
      if (!result.changes) return json(res, 404, { error: 'Project not found' });
      return json(res, 200, { id: Number(projectRoute[1]), defaultPriority: data.defaultPriority });
    }
    const name = data?.name;
    if (typeof name !== 'string' || !name.trim()) return json(res, 400, { error: 'Project name is required' });
    const cleanName = name.trim();
    const result = db.prepare('UPDATE projects SET name = ? WHERE id = ?').run(cleanName, Number(projectRoute[1]));
    if (!result.changes) return json(res, 404, { error: 'Project not found' });
    return json(res, 200, { id: Number(projectRoute[1]), name: cleanName });
  }
  const projectStateRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/archive$/);
  if (projectStateRoute && req.method === 'PATCH') {
    const data = await readBody(req);
    if (typeof data?.archived !== 'boolean') return json(res, 400, { error: 'Invalid request' });
    const result = db.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(data.archived ? 1 : 0, Number(projectStateRoute[1]));
    if (!result.changes) return json(res, 404, { error: 'Project not found' });
    return json(res, 200, { id: Number(projectStateRoute[1]), archived: data.archived });
  }
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    const data = await readBody(req);
    const name = data?.name;
    if (typeof name !== 'string' || !name.trim()) return json(res, 400, { error: 'Project name is required' });
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name.trim());
    return json(res, 201, { id: Number(result.lastInsertRowid), name: name.trim() });
  }
  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
  const moveRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/move$/);
  if (moveRoute && req.method === 'PATCH') {
    const sourceId = Number(moveRoute[1]);
    const taskId = Number(moveRoute[2]);
    const data = await readBody(req);
    const destinationId = Number(data?.destinationProjectId);
    const source = db.prepare('SELECT archived FROM projects WHERE id = ?').get(sourceId);
    const destination = db.prepare('SELECT archived FROM projects WHERE id = ?').get(destinationId);
    const task = db.prepare('SELECT id FROM tasks WHERE id = ? AND project_id = ?').get(taskId, sourceId);
    if (!source || !destination || !task) return json(res, 404, { error: 'Project or task not found' });
    if (source.archived || destination.archived || sourceId === destinationId) return json(res, 400, { error: 'Invalid destination project' });
    const order = db.prepare('SELECT COALESCE(MAX(sort_order), 0) + 1 AS next FROM tasks WHERE project_id = ?').get(destinationId).next;
    db.prepare('UPDATE tasks SET project_id = ?, sort_order = ? WHERE id = ? AND project_id = ?').run(destinationId, order, taskId, sourceId);
    return json(res, 200, { id: taskId, projectId: destinationId });
  }
  if (taskRoute) {
    const projectId = Number(taskRoute[1]);
    if (!db.prepare('SELECT id FROM projects WHERE id = ?').get(projectId)) return json(res, 404, { error: 'Project not found' });
    if (req.method === 'GET' && !taskRoute[2]) {
      return json(res, 200, db.prepare('SELECT id, project_id AS projectId, title, completed, priority, due_date AS dueDate FROM tasks WHERE project_id = ? ORDER BY sort_order, id').all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) })));
    }
    if (req.method === 'POST' && !taskRoute[2]) {
      const data = await readBody(req);
      const title = data?.title;
      if (typeof title !== 'string' || !title.trim()) return json(res, 400, { error: 'Task title is required' });
      const cleanTitle = title.trim();
      const project = db.prepare('SELECT default_priority FROM projects WHERE id = ?').get(projectId);
      const priority = project.default_priority || 'Normal';
      const order = db.prepare('SELECT COALESCE(MAX(sort_order), 0) + 1 AS next FROM tasks WHERE project_id = ?').get(projectId).next;
      const result = db.prepare('INSERT INTO tasks (project_id, title, priority, sort_order) VALUES (?, ?, ?, ?)').run(projectId, cleanTitle, priority, order);
      return json(res, 201, { id: Number(result.lastInsertRowid), projectId, title: cleanTitle, completed: false, priority });
    }
    if (req.method === 'PATCH' && taskRoute[2]) {
      const data = await readBody(req);
      if (typeof data?.title === 'string') {
        if (!data.title.trim()) return json(res, 400, { error: 'Task title is required' });
        const title = data.title.trim();
        const result = db.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?').run(title, Number(taskRoute[2]), projectId);
        if (!result.changes) return json(res, 404, { error: 'Task not found' });
        return json(res, 200, { id: Number(taskRoute[2]), projectId, title });
      }
      if (typeof data?.priority === 'string') {
        if (!['Low', 'Normal', 'High'].includes(data.priority)) return json(res, 400, { error: 'Invalid priority' });
        const result = db.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?').run(data.priority, Number(taskRoute[2]), projectId);
        if (!result.changes) return json(res, 404, { error: 'Task not found' });
        return json(res, 200, { id: Number(taskRoute[2]), projectId, priority: data.priority });
      }
      if (typeof data?.dueDate === 'string') {
        const dueDate = data.dueDate.trim();
        if (dueDate && !isValidDueDate(dueDate)) return json(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
        const savedDate = dueDate || null;
        const result = db.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?').run(savedDate, Number(taskRoute[2]), projectId);
        if (!result.changes) return json(res, 404, { error: 'Task not found' });
        return json(res, 200, { id: Number(taskRoute[2]), projectId, dueDate: savedDate });
      }
      if (typeof data?.completed !== 'boolean') return json(res, 400, { error: 'Invalid request' });
      const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(data.completed ? 1 : 0, Number(taskRoute[2]), projectId);
      if (!result.changes) return json(res, 404, { error: 'Task not found' });
      return json(res, 200, { id: Number(taskRoute[2]), projectId, completed: data.completed });
    }
  }
  if (req.method === 'GET' && url.pathname === '/') {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' }); return res.end(indexHtml);
  }
  if (req.method === 'GET' && url.pathname === '/app.js') {
    res.writeHead(200, { 'Content-Type': 'text/javascript; charset=utf-8' }); return res.end(appJs);
  }
  if (req.method === 'GET' && url.pathname === '/styles.css') {
    res.writeHead(200, { 'Content-Type': 'text/css; charset=utf-8' }); return res.end(stylesCss);
  }
  if (req.method === 'GET' && /^\/projects\/\d+$/.test(url.pathname)) {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' }); return res.end(indexHtml);
  }
  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' }); res.end('Not found');
});

server.listen(port, '0.0.0.0');
const root = document.querySelector('#app');

async function getProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}

async function getTasks(projectId) {
  const response = await fetch(`/api/projects/${projectId}/tasks`);
  if (!response.ok) throw new Error('Could not load tasks');
  return response.json();
}

function element(tag, text, className) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  if (className) node.className = className;
  return node;
}

async function showList() {
  root.replaceChildren();
  root.append(element('h1', 'Workboard'));
  const form = element('form', undefined, 'create-form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  input.autocomplete = 'off';
  const submit = element('button', 'Create project');
  submit.type = 'submit';
  form.append(label, input, submit);
  const error = element('p', undefined, 'alert');
  error.setAttribute('role', 'alert');
  error.hidden = true;
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      error.textContent = 'Project name is required';
      error.hidden = false;
      input.focus();
      return;
    }
    const response = await fetch('/api/projects', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });
    if (response.ok) {
      input.value = '';
      await showList();
    }
  });
  root.append(form, error);
  const filterLabel = element('label', 'Project filter');
  filterLabel.htmlFor = 'project-filter';
  const filter = element('select');
  filter.id = 'project-filter';
  for (const value of ['Active', 'Archived']) {
    const option = element('option', value);
    option.value = value;
    filter.append(option);
  }
  root.append(filterLabel, filter);
  const list = element('section', undefined, 'projects');
  list.setAttribute('aria-label', 'Projects');
  root.append(list);
  async function renderProjects() {
   try {
    const projects = await getProjects();
    list.replaceChildren();
    for (const project of projects) {
      if ((filter.value === 'Archived') !== project.archived) continue;
      const row = element('div', undefined, 'project-row');
      row.dataset.testid = 'project-row';
      row.append(element('span', project.name));
      const summary = element('span', `${project.completedCount}/${project.totalCount} completed`);
      summary.dataset.testid = 'project-summary';
      row.append(summary);
      const open = element('button', 'Open project');
      open.type = 'button';
      open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
      row.append(open);
      const archive = element('button', project.archived ? 'Restore project' : 'Archive project');
      archive.type = 'button';
      archive.addEventListener('click', async () => {
        const response = await fetch(`/api/projects/${project.id}/archive`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ archived: !project.archived }),
        });
        if (response.ok) await renderProjects();
      });
      row.append(archive);
      list.append(row);
    }
   } catch {
    const message = element('p', 'Could not load projects');
    message.setAttribute('role', 'alert');
    list.replaceChildren(message);
   }
  }
  filter.addEventListener('change', renderProjects);
  await renderProjects();
}

async function showProject(id) {
  root.replaceChildren();
  const back = element('button', 'Projects');
  back.type = 'button';
  back.addEventListener('click', () => { location.href = '/'; });
  root.append(back);
  try {
    const projects = await getProjects();
    const project = projects.find((item) => String(item.id) === id);
    if (project) {
      const heading = element('h1', project.name);
      root.append(heading);
      if (project.archived) root.append(element('p', 'Archived project'));
      const renameForm = element('form', undefined, 'create-form');
      const renameLabel = element('label', 'New project name');
      renameLabel.htmlFor = 'new-project-name';
      const renameInput = element('input');
      renameInput.id = 'new-project-name';
      renameInput.name = 'name';
      renameInput.type = 'text';
      renameInput.autocomplete = 'off';
      renameInput.disabled = project.archived;
      const renameButton = element('button', 'Rename project');
      renameButton.type = 'submit';
      renameButton.disabled = project.archived;
      renameForm.append(renameLabel, renameInput, renameButton);
      const renameError = element('p', undefined, 'alert');
      renameError.setAttribute('role', 'alert');
      renameError.hidden = true;
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = renameInput.value.trim();
        if (!name) {
          renameError.textContent = 'Project name is required';
          renameError.hidden = false;
          renameInput.focus();
          return;
        }
        const response = await fetch(`/api/projects/${id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
        });
        if (response.ok) {
          heading.textContent = name;
          renameInput.value = '';
          renameError.hidden = true;
        }
      });
      root.append(renameForm, renameError);
      const defaultLabel = element('label', 'Default task priority');
      defaultLabel.htmlFor = 'default-task-priority';
      const defaultPriority = element('select');
      defaultPriority.id = 'default-task-priority';
      for (const value of ['Low', 'Normal', 'High']) {
        const option = element('option', value);
        option.value = value;
        defaultPriority.append(option);
      }
      defaultPriority.value = project.defaultPriority || 'Normal';
      defaultPriority.disabled = project.archived;
      defaultPriority.addEventListener('change', async () => {
        const response = await fetch(`/api/projects/${id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ defaultPriority: defaultPriority.value }),
        });
        if (!response.ok) defaultPriority.value = project.defaultPriority || 'Normal';
      });
      root.append(defaultLabel, defaultPriority);
      await renderTasks(id, project.archived);
    } else root.append(element('h1', 'Project not found'));
  } catch {
    root.append(element('h1', 'Could not load project'));
  }
}

async function renderTasks(projectId, archived) {
  const form = element('form', undefined, 'create-form');
  const label = element('label', 'Task title');
  label.htmlFor = 'task-title';
  const input = element('input');
  input.id = 'task-title';
  input.name = 'title';
  input.type = 'text';
  input.autocomplete = 'off';
  const submit = element('button', 'Create task');
  submit.type = 'submit';
  submit.disabled = archived;
  form.append(label, input, submit);
  const error = element('p', undefined, 'alert');
  error.setAttribute('role', 'alert');
  error.hidden = true;
  const filterLabel = element('label', 'Task filter');
  filterLabel.htmlFor = 'task-filter';
  const filter = element('select');
  filter.id = 'task-filter';
  for (const value of ['All', 'Open', 'Completed']) {
    const option = element('option', value);
    option.value = value;
    filter.append(option);
  }
  const priorityFilterLabel = element('label', 'Priority filter');
  priorityFilterLabel.htmlFor = 'priority-filter';
  const priorityFilter = element('select');
  priorityFilter.id = 'priority-filter';
  for (const value of ['All', 'Low', 'Normal', 'High']) {
    const option = element('option', value);
    option.value = value;
    priorityFilter.append(option);
  }
  const dueFromLabel = element('label', 'Due from');
  dueFromLabel.htmlFor = 'due-from';
  const dueFrom = element('input');
  dueFrom.type = 'text';
  dueFrom.id = 'due-from';
  dueFrom.setAttribute('aria-label', 'Due from');
  const dueThroughLabel = element('label', 'Due through');
  dueThroughLabel.htmlFor = 'due-through';
  const dueThrough = element('input');
  dueThrough.type = 'text';
  dueThrough.id = 'due-through';
  dueThrough.setAttribute('aria-label', 'Due through');
  const applyDueRange = element('button', 'Apply due range');
  applyDueRange.type = 'button';
  const rangeError = element('p', undefined, 'alert');
  rangeError.setAttribute('role', 'alert');
  rangeError.hidden = true;
  let appliedRange = { from: '', through: '' };
  const rows = element('section', undefined, 'tasks');
  rows.setAttribute('aria-label', 'Tasks');
  async function refresh() {
    const tasks = await getTasks(projectId);
    const projects = await getProjects();
    const destinations = projects.filter(project => !project.archived && String(project.id) !== String(projectId));
    rows.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed) continue;
      if (filter.value === 'Completed' && !task.completed) continue;
      if (priorityFilter.value !== 'All' && task.priority !== priorityFilter.value) continue;
      if (appliedRange.from || appliedRange.through) {
        if (!task.dueDate) continue;
        if (appliedRange.from && task.dueDate < appliedRange.from) continue;
        if (appliedRange.through && task.dueDate > appliedRange.through) continue;
      }
      const row = element('div', undefined, 'task-row');
      row.dataset.testid = 'task-row';
      row.append(element('span', task.title));
      const checkbox = element('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = archived;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        const response = await fetch(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }),
        });
        if (response.ok) await refresh();
      });
      row.append(checkbox);
      const priority = element('select');
      priority.setAttribute('aria-label', 'Task priority');
      for (const value of ['Low', 'Normal', 'High']) {
        const option = element('option', value);
        option.value = value;
        priority.append(option);
      }
      priority.value = task.priority || 'Normal';
      priority.disabled = archived;
      priority.addEventListener('change', async () => {
        const selectedPriority = priority.value;
        priority.disabled = true;
        const response = await fetch(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ priority: selectedPriority }),
        });
        if (response.ok) await refresh();
        else {
          priority.value = task.priority || 'Normal';
          priority.disabled = false;
        }
      });
      row.append(priority);
      const dueDate = element('input');
      dueDate.type = 'text';
      dueDate.setAttribute('aria-label', 'Task due date');
      dueDate.value = task.dueDate || '';
      dueDate.disabled = archived;
      const saveDueDate = element('button', 'Save due date');
      saveDueDate.type = 'button';
      saveDueDate.disabled = archived;
      const dueDateError = element('span');
      dueDateError.setAttribute('role', 'alert');
      saveDueDate.addEventListener('click', async () => {
        const response = await fetch(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ dueDate: dueDate.value }),
        });
        if (response.ok) {
          dueDateError.textContent = '';
          await refresh();
        } else {
          const result = await response.json().catch(() => ({}));
          dueDateError.textContent = result.error || 'Could not save due date';
        }
      });
      row.append(dueDate, saveDueDate, dueDateError);
      const renameInput = element('input');
      renameInput.type = 'text';
      renameInput.setAttribute('aria-label', 'New task title');
      renameInput.disabled = archived;
      const renameButton = element('button', 'Rename task');
      renameButton.type = 'button';
      renameButton.disabled = archived;
      const renameError = element('span');
      renameError.setAttribute('role', 'alert');
      renameButton.addEventListener('click', async () => {

      renameButton.addEventListener('click', async () => {
        const title = renameInput.value.trim();
        if (!title) {
          renameError.textContent = 'Task title is required';
          renameInput.focus();
          return;
        }
        const response = await fetch(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
        });
        if (response.ok) await refresh();
      });
      row.append(renameInput, renameButton, renameError);
      const destination = element('select');
      destination.setAttribute('aria-label', 'Destination project');
      for (const candidate of destinations) {
        const option = element('option', candidate.name);
        option.value = candidate.id;
        destination.append(option);
      }
      const moveButton = element('button', 'Move task');
      moveButton.type = 'button';
      destination.disabled = archived || destinations.length === 0;
      moveButton.disabled = archived || destinations.length === 0;
      moveButton.addEventListener('click', async () => {
        const response = await fetch(`/api/projects/${projectId}/tasks/${task.id}/move`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ destinationProjectId: Number(destination.value) }),
        });
        if (response.ok) await refresh();
      });
      row.append(destination, moveButton);
      rows.append(row);
    }
  }
  filter.addEventListener('change', refresh);
  priorityFilter.addEventListener('change', refresh);
  applyDueRange.addEventListener('click', async () => {
    const from = dueFrom.value.trim();
    const through = dueThrough.value.trim();
    const validDate = value => {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
